# explore derivability of sub for small types (no binders except mu, bvar0 only)
import sys
from functools import lru_cache
sys.setrecursionlimit(100000)

# type repr as tuples
NAT=('nat',)
TOP=('top',)
BV=('bv',0)
def FV(x): return ('fvar',x)
def ARR(a,b): return ('arr',a,b)
def MU(a): return ('mu',a)
def LAB(x,a): return ('lab',x,a)
RNIL=('rnil',)
def RC(l,t,tl): return ('rcons',l,t,tl)

XF='@x'  # fresh var/label

def show(t):
    k=t[0]
    if k=='nat': return 'nat'
    if k=='top': return 'Top'
    if k=='bv': return f'#{t[1]}'
    if k=='fvar': return t[1]
    if k=='arr': return f'({show(t[1])}->{show(t[2])})'
    if k=='mu': return f'mu({show(t[1])})'
    if k=='lab': return f'lab[{t[1]}]{show(t[2])}'
    if k=='rnil': return '{}'
    if k=='rcons': return f'{{{t[1]}:{show(t[2])}|{show(t[3])}}}'
    return '?'

def subst_bv0(u,t):
    # replace bv0 by u; no binders for deeper
    k=t[0]
    if k=='bv':
        return u if t[1]==0 else t
    if k in ('nat','top','rnil','fvar'): return t
    if k=='arr': return ARR(subst_bv0(u,t[1]),subst_bv0(u,t[2]))
    if k=='mu': return MU(subst_bv0(u,t[1]))  # binder: bv0 inside is shadowed bound; but open_tt_rec increments, so bv0 inside mu refers to inner, not subst. Approx: only handle bodies with bv0 at top-level; for simplicity do nothing inside mu
    if k=='lab': return LAB(t[1],subst_bv0(u,t[2]))
    if k=='rcons': return RC(t[1],subst_bv0(u,t[2]),subst_bv0(u,t[3]))
    return t

def openA(A,U):
    # for bodies A of mu (no nested mu binder issues assumed)
    k=A[0]
    if k=='bv':
        return U if A[1]==0 else A
    if k in ('nat','top','rnil','fvar'): return A
    if k=='arr': return ARR(openA(A[1],U),openA(A[2],U))
    if k=='lab': return LAB(A[1],openA(A[2],U))
    if k=='rcons': return RC(A[1],openA(A[2],U),openA(A[3],U))
    if k=='mu': return MU(A[1])  # crude: shading
    return A

def f(A):
    # open A (lab X (open A X))
    return openA(A, LAB(XF, openA(A, FV(XF))))

def collectLabel(t):
    k=t[0]
    if k=='rcons': return {t[1]} | collectLabel(t[3])
    return set()

def rt_type(t):
    return t[0] in ('rnil','rcons')

def tlookup(l,t):
    k=t[0]
    if k=='rcons':
        if t[1]==l: return t[2]
        return tlookup(l,t[3])
    return None

# --- WF in context nil (no bindings) or Xtop (binds X -> sub top) ---
import functools
@functools.lru_cache(maxsize=None)
def wf(ctx,t,depth):
    if depth<=0: return False
    k=t[0]
    if k in ('nat','top','rnil'): return True
    if k=='fvar': return ctx=='Xtop' and t[1]==XF
    if k=='bv': return False
    if k=='arr': return wf(ctx,t[1],depth-1) and wf(ctx,t[2],depth-1)
    if k=='lab': return wf(ctx,t[2],depth-1)
    if k=='rcons':
        return (wf(ctx,t[2],depth-1) and wf(ctx,t[3],depth-1) and rt_type(t[3])
                and (t[1] not in collectLabel(t[3])))
    if k=='mu':
        A=t[1]
        # forall fresh X: WF (X~top) (open A X) and WF (X~top) (open A (lab X (open A X)))
        o1=openA(A,FV(XF)); o2=f(A)
        return wf('Xtop',o1,depth-1) and wf('Xtop',o2,depth-1)
    return False

@functools.lru_cache(maxsize=None)
def issub(ctx,A,B,depth):
    if depth<=0: return False
    # basic structural rules
    if B==TOP and wf(ctx,A,depth): return True
    if A==NAT and B==NAT: return True
    if A[0]=='fvar' and B[0]=='fvar' and A==B and wf(ctx,A,depth): return True
    # trans_tvar: context Xtop binds X~top
    if ctx=='Xtop' and A==FV(XF) and issub('nil',TOP,B,depth-1): return True
    if A[0]=='arr' and B[0]=='arr':
        if issub(ctx,B[1],A[1],depth-1) and issub(ctx,A[2],B[2],depth-1): return True
    if A[0]=='lab' and B[0]=='lab' and A[1]==B[1]:
        if issub(ctx,A[2],B[2],depth-1): return True
    if A[0]=='rcons' or A[0]=='rnil':
        if rt_type(A) and rt_type(B) and collectLabel(B) <= collectLabel(A) and wf(ctx,A,depth-1) and wf(ctx,B,depth-1):
            ok=True
            labs=collectLabel(A)&collectLabel(B)
            for l in labs:
                t1=tlookup(l,A); t2=tlookup(l,B)
                if t1 is None or t2 is None or not issub(ctx,t1,t2,depth-1):
                    ok=False;break
            if ok: return True
    if A[0]=='mu' and B[0]=='mu':
        A1=A[1]; A2=B[1]
        # kernel at fresh X
        if wf('Xtop',openA(A1,FV(XF)),depth-1) and wf('Xtop',openA(A2,FV(XF)),depth-1) and issub('Xtop',f(A1),f(A2),depth-1):
            return True
    return False

def sub(depth,A,B):
    return issub('nil',A,B,depth)

# enumerate small bodies (buildup with bv0 allowed once)
def bodies(sz):
    if sz<=0: return []
    res=[NAT,TOP,BV,RNIL, MU(TOP)]
    if sz>=2:
        for a in bodies(sz-1):
            res.append(ARR(TOP,a)); res.append(ARR(a,TOP)); res.append(LAB('l',a)); res.append(MU(a))
    if sz>=3:
        for a in bodies(sz-2):
            for b in bodies(sz-2):
                res.append(ARR(a,b)); res.append(RC('f',a,RNIL)); res.append(RC('g',a,RNIL))
    # dedupe
    return list(dict.fromkeys(res))

B = bodies(3)
print("num bodies", len(B))
DEPTH=6
# find chains where goal fails
fails=[]
for A0 in B:
    for T2 in B:
        if not sub(DEPTH, MU(A0), MU(T2)): continue
        for AS in B:
            if not sub(DEPTH, MU(T2), MU(AS)): continue
            for TM in B:
                if not sub(DEPTH, MU(AS), MU(TM)): continue
                goal = sub(DEPTH, openA(A0, MU(T2)), openA(TM, MU(AS)))
                if not goal:
                    fails.append((A0,T2,AS,TM))
print("fails:", len(fails))
for (A0,T2,AS,TM) in fails[:20]:
    print("A0=",show(A0),"T2=",show(T2),"AS=",show(AS),"TM=",show(TM),
          "| vtype=",show(openA(A0,MU(T2))), "goal=",show(openA(TM,MU(AS))))
