import sys; sys.path.insert(0,'/tmp/explore')
# Monolithic stronger model: sa_rec requires kernel relation at 3 fresh labels, no fvars in bodies.
import functools, itertools, random
NAT=('nat',); TOP=('top',); BV=('bv',0); RNIL=('rnil',)
def ARR(a,b): return ('arr',a,b)
def MU(a): return ('mu',a)
def LAB(x,a): return ('lab',x,a)
def RC(l,t,tl): return ('rcons',l,t,tl)
XSF=['@a','@b','@c']
def show(t):
    k=t[0]
    return {'nat':lambda:'nat','top':lambda:'Top','bv':lambda:'#'+str(t[1]),'arr':lambda:f'({show(t[1])}->{show(t[2])})','mu':lambda:f'mu({show(t[1])})','lab':lambda:f'lab[{t[1]}]{show(t[2])}','rnil':lambda:'{}','rcons':lambda:f'{{{t[1]}:{show(t[2])}|{show(t[3])}}}','fvar':lambda:t[1]}[k]()
def openA(A,U):
    k=A[0]
    if k=='bv': return U if A[1]==0 else A
    if k in ('nat','top','rnil','fvar'): return A
    if k=='arr': return ARR(openA(A[1],U),openA(A[2],U))
    if k=='lab': return LAB(A[1],openA(A[2],U))
    if k=='rcons': return RC(A[1],openA(A[2],U),openA(A[3],U))
    if k=='mu': return MU(A[1])  # shade
    return A
def f(A,X): return openA(A,LAB(X,openA(A,('fvar',X))))
def collectLabel(t):
    return {t[1]}|collectLabel(t[3]) if t[0]=='rcons' else set()
def rt_type(t): return t[0] in ('rnil','rcons')
def tlookup(l,t):
    if t[0]=='rcons': return t[2] if t[1]==l else tlookup(l,t[3])
    return None
@functools.lru_cache(maxsize=None)
def wf(ctx,t,depth):
    if depth<=0: return False
    k=t[0]
    if k in ('nat','top','rnil'): return True
    if k=='fvar': return t[1] in ctx
    if k=='bv': return False
    if k=='arr': return wf(ctx,t[1],depth-1) and wf(ctx,t[2],depth-1)
    if k=='lab': return wf(ctx,t[2],depth-1)
    if k=='rcons': return wf(ctx,t[2],depth-1) and wf(ctx,t[3],depth-1) and rt_type(t[3]) and t[1] not in collectLabel(t[3])
    if k=='mu':
        A=t[1]
        return all(wf(frozenset([X]),openA(A,('fvar',X)),depth-1) and wf(frozenset([X]),f(A,X),depth-1) for X in XSF)
    return False
@functools.lru_cache(maxsize=None)
def issub(ctx,A,B,depth):
    if depth<=0: return False
    if B==TOP and wf(ctx,A,depth): return True
    if A==NAT and B==NAT: return True
    if A[0]=='fvar' and B[0]=='fvar' and A==B and wf(ctx,A,depth): return True
    if A[0]=='fvar' and A[1] in ctx and issub(frozenset(),TOP,B,depth-1): return True  # trans_tvar with binding top
    if A[0]=='arr' and B[0]=='arr':
        if issub(ctx,B[1],A[1],depth-1) and issub(ctx,A[2],B[2],depth-1): return True
    if A[0]=='lab' and B[0]=='lab' and A[1]==B[1] and issub(ctx,A[2],B[2],depth-1): return True
    if A[0] in ('rcons','rnil'):
        if rt_type(A) and rt_type(B) and collectLabel(B)<=collectLabel(A) and wf(ctx,A,depth-1) and wf(ctx,B,depth-1):
            ok=True
            for l in collectLabel(A)&collectLabel(B):
                t1=tlookup(l,A); t2=tlookup(l,B)
                if t1 is None or t2 is None or not issub(ctx,t1,t2,depth-1): ok=False;break
            if ok: return True
    if A[0]=='mu' and B[0]=='mu':
        A1=A[1];B1=B[1]
        # require for all fresh labels
        if all(wf(frozenset([X]),openA(A1,('fvar',X)),depth-1) and wf(frozenset([X]),openA(B1,('fvar',X)),depth-1) and issub(frozenset([X]),f(A1,X),f(B1,X),depth-1) for X in XSF):
            return True
