import functools, random, sys
sys.setrecursionlimit(100000)
# faithful-ish types with de Bruijn indices and typ_all
NAT=('nat',); TOP=('top',); RNIL=('rnil',)
def BV(k): return ('bv',k)
def FV(x): return ('fvar',x)
def ARR(a,b): return ('arr',a,b)
def ALL(s,t): return ('all',s,t)
def MU(a): return ('mu',a)
def LAB(l,a): return ('lab',l,a)
def RC(l,t,tl): return ('rcons',l,t,tl)

POOL=['@a','@b','@c','@d']

def show(t):
    k=t[0]
    if k=='nat': return 'nat'
    if k=='top': return 'Top'
    if k=='bv': return '#'+str(t[1])
    if k=='fvar': return t[1]
    if k=='arr': return f'({show(t[1])}->{show(t[2])})'
    if k=='all': return f'(A{show(t[1])}.{show(t[2])})'
    if k=='mu': return f'mu({show(t[1])})'
    if k=='lab': return f'lab[{t[1]}]{show(t[2])}'
    if k=='rnil': return '{}'
    if k=='rcons': return f'{{{t[1]}:{show(t[2])}|{show(t[3])}}}'

def orec(k,U,A):
    c=A[0]
    if c=='bv': return U if A[1]==k else A
    if c in ('nat','top','rnil','fvar'): return A
    if c=='arr': return ARR(orec(k,U,A[1]),orec(k,U,A[2]))
    if c=='all': return ALL(orec(k,U,A[1]),orec(k+1,U,A[2]))
    if c=='mu': return MU(orec(k+1,U,A[1]))
    if c=='lab': return LAB(A[1],orec(k,U,A[2]))
    if c=='rcons': return RC(A[1],orec(k,U,A[2]),orec(k,U,A[3]))

def open0(A,U): return orec(0,U,A)
def f(A,X): return open0(A, LAB(X, open0(A,FV(X))))

def collectLabel(t):
    return {t[1]}|collectLabel(t[3]) if t[0]=='rcons' else set()
def rt_type(t): return t[0] in ('rnil','rcons')
def tlookup(l,t):
    if t[0]=='rcons': return t[2] if t[1]==l else tlookup(l,t[3])
    return None

def fresh(ctx,n=3):
    r=[x for x in POOL if x not in ctx]
    return r[:n]

@functools.lru_cache(maxsize=None)
def wf(ctx,t,depth):
    if depth<=0: return False
    c=t[0]
    if c in ('nat','top','rnil'): return True
    if c=='fvar': return t[1] in ctx
    if c=='bv': return False
    if c=='arr': return wf(ctx,t[1],depth-1) and wf(ctx,t[2],depth-1)
    if c=='lab': return wf(ctx,t[2],depth-1)
    if c=='rcons': return wf(ctx,t[2],depth-1) and wf(ctx,t[3],depth-1) and rt_type(t[3]) and t[1] not in collectLabel(t[3])
    if c=='mu':
        A=t[1]; fs=fresh(ctx)
        if not fs: return False
        return all(wf(ctx|{X},open0(A,FV(X)),depth-1) and wf(ctx|{X},f(A,X),depth-1) for X in fs)
    if c=='all':
        S,T=t[1],t[2]; fs=fresh(ctx)
        if not fs: return False
        return wf(ctx,S,depth-1) and all(wf(ctx|{X},open0(T,FV(X)),depth-1) for X in fs)
    return False

@functools.lru_cache(maxsize=None)
def issub(ctx,A,B,depth):
    if depth<=0: return False
    if B==TOP and wf(ctx,A,depth): return True
    if A==NAT and B==NAT: return True
    if A[0]=='fvar' and B[0]=='fvar' and A==B and wf(ctx,A,depth): return True
    if A[0]=='fvar' and A[1] in ctx and issub(frozenset(),TOP,B,depth-1): return True
    if A[0]=='arr' and B[0]=='arr':
        if issub(ctx,B[1],A[1],depth-1) and issub(ctx,A[2],B[2],depth-1): return True
    if A[0]=='lab' and B[0]=='lab' and A[1]==B[1] and issub(ctx,A[2],B[2],depth-1): return True
    if A[0]=='all' and B[0]=='all':
        fs=fresh(ctx)
        if fs and issub(ctx,A[1],B[1],depth-1) and issub(ctx,B[1],A[1],depth-1) and all(
             issub(ctx|{X},open0(A[2],FV(X)),open0(B[2],FV(X)),depth-1) for X in fs):
            return True
    if A[0] in ('rcons','rnil'):
        if rt_type(A) and rt_type(B) and collectLabel(B)<=collectLabel(A) and wf(ctx,A,depth-1) and wf(ctx,B,depth-1):
            ok=True
            for l in collectLabel(A)&collectLabel(B):
                t1=tlookup(l,A); t2=tlookup(l,B)
                if t1 is None or t2 is None or not issub(ctx,t1,t2,depth-1): ok=False;break
            if ok: return True
    if A[0]=='mu' and B[0]=='mu':
        fs=fresh(ctx)
        if fs:
            A1=A[1];B1=B[1]
            if all(wf(ctx|{X},open0(A1,FV(X)),depth-1) and wf(ctx|{X},open0(B1,FV(X)),depth-1) and issub(ctx|{X},f(A1,X),f(B1,X),depth-1) for X in fs):
                return True
    return False

def sub(d,A,B): return issub(frozenset(),A,B,d)

def bodies(sz):
    base=[NAT,TOP,BV(0),RNIL,MU(TOP),MU(BV(0))]
    cur=list(dict.fromkeys(base)); allb=list(cur)
    for _ in range(sz-1):
        nxt=[]
        for a in cur:
            nxt += [ARR(a,TOP),ARR(TOP,a),ARR(a,a),LAB('l',a),MU(a),RC('k',a,RNIL),RC('k',TOP,a),ALL(TOP,a)]
        nxt=list(dict.fromkeys(nxt)); allb+=nxt; cur=nxt
    return list(dict.fromkeys(allb))
