# Named types: ('top',), ('nat',), ('var',name), ('arrow',a,b), ('mu',X,body), ('label',X,t)
# env: dict name -> bound type (we only use top) ; use 'top' sentinel type ('top',)
TOP=('top',); NAT=('nat',)
def var(x): return ('var',x)
def arr(a,b): return ('arrow',a,b)
def mu(x,b): return ('mu',x,b)
def lab(x,t): return ('label',x,t)

def free(t):
    k=t[0]
    if k in ('top','nat'): return set()
    if k=='var': return {t[1]}
    if k in ('arrow',): return free(t[1])|free(t[2])
    if k=='mu': return free(t[2])-{t[1]}
    if k=='label': return free(t[2])  # label name is not a type variable
    raise Exception(t)

def freshen(t, avoid):
    # alpha-rename binders to fresh names not in avoid or free(t)
    k=t[0]
    if k in ('top','nat'): return t
    if k=='var': return t
    if k=='arrow': return arr(freshen(t[1],avoid), freshen(t[2],avoid))
    if k=='label': return lab(t[1], freshen(t[2],avoid))
    if k=='mu':
        X,b=t[1],t[2]
        # choose fresh name
        n=0
        while True:
            nm=X+("_"*n)
            if nm not in avoid and nm not in free(b) and nm!=X:
                break
            n+=1
        # rename binder X to nm in b (capture avoiding), then recurse
        b2=subst(b,X,var(nm))
        return mu(nm, freshen(b2, avoid|{nm}))
    raise Exception(t)

def subst(t, X, U):
    # capture-avoiding substitution of free var X by U
    k=t[0]
    if k in ('top','nat'): return t
    if k=='var':
        return U if t[1]==X else t
    if k=='arrow': return arr(subst(t[1],X,U), subst(t[2],X,U))
    if k=='label': return lab(t[1], subst(t[2],X,U))
    if k=='mu':
        Y,b=t[1],t[2]
        if Y==X: return t
        if Y in free(U):
            # rename Y
            n=0
            while True:
                nm=Y+("_"*(n+1))
                if nm not in free(b) and nm not in free(U) and nm!=X: break
                n+=1
            b=subst(b,Y,var(nm)); Y=nm
        return mu(Y, subst(b,X,U))
    raise Exception(t)

def open_mu(t, W):
    # t = mu X b ; open with W
    assert t[0]=='mu'
    return subst(t[2], t[1], W)

def wf(env, t):
    k=t[0]
    if k in ('top','nat'): return True
    if k=='var': return t[1] in env
    if k=='arrow': return wf(env,t[1]) and wf(env,t[2])
    if k=='label': return wf(env,t[2])
