import sys, itertools
sys.setrecursionlimit(1000000)
TOP=('top',); NAT=('nat',)
def var(x): return ('var',x)
def arr(a,b): return ('arrow',a,b)
def mu(x,b): return ('mu',x,b)
def lab(x,t): return ('label',x,t)
def all(x,s,t): return ('all',x,s,t)

def free(t):
    k=t[0]
    if k in ('top','nat'): return frozenset()
    if k=='var': return frozenset([t[1]])
    if k=='arrow': return free(t[1])|free(t[2])
    if k=='label': return free(t[2])
    if k=='mu': return free(t[2])-{t[1]}
    if k=='all': return free(t[2])|(free(t[3])-{t[1]})
    raise Exception(t)

_name=0
def fresh(avoid):
    global _name
    while True:
        n="v%d"%_name; _name+=1
        if n not in avoid: return n

def subst(t,X,U):
    k=t[0]
    if k in ('top','nat'): return t
    if k=='var': return U if t[1]==X else t
    if k=='arrow': return arr(subst(t[1],X,U),subst(t[2],X,U))
    if k=='label': return lab(t[1],subst(t[2],X,U))
    if k=='mu':
        Y,b=t[1],t[2]
        if Y==X: return t
        if Y in free(U):
            nm=fresh(free(b)|free(U)|{X})
            b=subst(b,Y,var(nm)); Y=nm
        return mu(Y,subst(b,X,U))
    if k=='all':
        Y,S,T=t[1],t[2],t[3]
        S=subst(S,X,U)
        if Y==X: return all(Y,S,T)
        if Y in free(U):
            nm=fresh(free(T)|free(U)|{X})
            T=subst(T,Y,var(nm)); Y=nm
        return all(Y,S,subst(T,X,U))
    raise Exception(t)

def wfe(env, order=None):
    if order is None: order=list(env.items())
    if not order: return True
    items=sorted(env.items(), key=lambda kv: kv[0])
    for k,(name,U) in enumerate(order):
        rest={n:t for n,t in order[:k]}
        if not wf(rest,U): return False
    return True

memo={}
def sub(env,A,B,depth=0):
    key=(tuple(sorted(env.items(),key=lambda kv:kv[0])),A,B)
    if key in memo: return memo[key]
    if depth>40: return False
    r=check(env,A,B,depth)
    memo[key]=r
    return r

def wf(env,t):
    k=t[0]
    if k in ('top','nat'): return True
    if k=='var': return t[1] in env
    if k=='arrow': return wf(env,t[1]) and wf(env,t[2])
    if k=='label': return wf(env,t[2])
    if k=='mu':
        X,b=t[1],t[2]; z=fresh(set(env)|free(b)|{X})
        e2={**env,z:TOP}
        return wf(e2,subst(b,X,var(z))) and wf(e2,subst(b,X,lab(z,subst(b,X,var(z)))))
    if k=='all':
        X,S,T=t[1],t[2],t[3]
        if not wf(env,S): return False
        z=fresh(set(env)|free(T)|{X})
        return wf({**env,z:S},subst(T,X,var(z)))
    raise Exception(t)

def check(env,A,B,depth):
    if A==NAT and B==NAT: return wfe(env)
    if B==TOP:
        return wfe(env) and wf(env,A)
    # fvar
    if A[0]=='var':

    if A[0]=='var':
        a=A[1]
