        return sub(env,B[1],A[1],depth+1) and sub(env,A[2],B[2],depth+1)
    if A[0]=='label' and B[0]=='label':
        return A[1]==B[1] and sub(env,A[2],B[2],depth+1)
    if A[0]=='mu' and B[0]=='mu':
        (XA,bA),(XB,bB)=A[1:],B[1:]
        z=fresh(set(env)|free(A)|free(B)|{XA,XB})
        left=subst(bA,XA,lab(z,subst(bA,XA,var(z))))
        right=subst(bB,XB,lab(z,subst(bB,XB,var(z))))
