# generate ground types (no free vars) of bounded size
def gen_ground(depth, maxnodes):
    if depth<=0: return
    yield TOP; yield NAT
    if depth>=1:
        for a in gen_ground(depth-1,maxnodes):
            for b in gen_ground(depth-1,maxnodes):
                yield arr(a,b)
        # all with closed S and T over X, small
        for S in gen_ground(depth-1,maxnodes):
            for T in gen_body(depth-1,maxnodes,{'x':S},allow_self=False):
                yield all('x',S,T)
