            for b in gen_body(depth-1,maxnodes,envvars,allow_self):
                yield arr(a,b)
        for S in gen_body(depth-1,maxnodes,envvars,allow_self):
            for T in gen_body(depth-1,maxnodes,{**envvars,'y':S},allow_self):
                yield all('y',S,T)

def gb(depth, envvars, allow_self):
    seen=set()
    for t in gen_body(depth, 0, envvars, allow_self):
        if t not in seen:
            seen.add(t); yield t

ops=list(gb(2, {'x':TOP}, True))
print("num ops", len(ops))
# cap
ops=ops[:400]
cnt=0; found=0
for Aop in ops:
    for Bop in ops:
        mA=mu('x',Aop); mB=mu('x',Bop)
        # only closed mu types (ops have free only x)
        H=sub({},mA,mB)
        if H:
