                if found>20: sys.exit()
print("H true count",cnt,"counterexamples",found)

# curated ground types
def M(body): return mu('x',body)
x=var('x')
bodies=[TOP,NAT,x,arr(x,x),arr(x,TOP),arr(TOP,x),lab('l',x)]
op_bodies=[]
for b in bodies: op_bodies.append(b)
for a in bodies:
    for b in bodies: op_bodies.append(arr(a,b))
mus=[M(b) for b in op_bodies]
base=[TOP,NAT]+mus
# all types over closed S and T with var y
closed_small=[TOP,NAT]+mus
allts=[]
for S in closed_small:
    for T in [TOP,NAT,var('y'),arr(var('y'),TOP),arr(TOP,var('y')),S]:
        allts.append(all('y',S,T))
labels=[lab('l',t) for t in [TOP,NAT]+mus]
gs=[]
seen=set()
for t in base+allts+labels:
    if free(t)==frozenset() and t not in seen:
