print("gs",len(gs))
subs=[(A,B) for A in gs for B in gs if sub({},A,B)]
print("subpairs",len(subs))
from collections import defaultdict
out=defaultdict(list)
for (A,B) in subs: out[A].append(B)
bad=0
for (A,B) in subs:
