def atoms(T, s):
    if T[0]=='fvar': s.add(T[1])
    elif T[0]=='label': s.add(T[1]); atoms(T[2],s)
    elif T[0] in ('arrow',): atoms(T[1],s); atoms(T[2],s)
    elif T[0]=='all': atoms(T[1],s); atoms(T[2],s)
    elif T[0]=='mu': atoms(T[1],s)
    return s

def collect(T,s):
    if T[0]=='fvar': s.add(T[1])
    elif T[0]=='label': s.add(T[1]); collect(T[2],s)
    elif T[0]=='arrow' or T[0]=='all': collect(T[1],s); collect(T[2],s)
    elif T[0]=='mu': collect(T[1],s)
    return s

# open_rec k U T, matching open_tt_rec (U assumed closed w.r.t bvars)
def orec(k,U,T):
    c=T[0]
    if c in ('top','nat'): return T
    if c=='bvar': return U if T[1]==k else T
    if c=='fvar': return T
    if c=='arrow': return ('arrow',orec(k,U,T[1]),orec(k,U,T[2]))
    if c=='all': return ('all',orec(k,U,T[1]),orec(k+1,U,T[2]))
    if c=='mu': return ('mu',orec(k+1,U,T[1]))
    if c=='label': return ('label',T[1],orec(k,U,T[2]))
    if c=='rcd_nil': return T
    if c=='rcd_cons': return ('rcd_cons',T[1],orec(k,U,T[2]),orec(k,U,T[3]))
