Lemma wf_mu_unfold : forall (A : typ),
  WF nil (typ_mu A) -> WF nil (open_tt A (typ_mu A)).
Proof.
  intros A Hwf. inversion Hwf; subst.
  match goal with
  | H : forall X : atom, X \\notin ?L ->
        WF (X ~ bind_sub typ_top ++ nil)
           (open_tt ?A0 (typ_label X (open_tt A0 X))) |- _ =>
      destruct (atom_fresh (L \\u fv_tt A0 \\u fl_tt A0)) as [X HX];
      assert (HXL : X \\notin L) by fsetdec;
      assert (HXfv : X \\notin fv_tt A0) by fsetdec;
      assert (HXfl : X \\notin fl_tt A0) by fsetdec;
      pose proof (H X HXL) as Hlab;
      pose proof (@wf_erase (X ~ bind_sub typ_top ++ nil)
                    (open_tt A0 (typ_label X (open_tt A0 X))) Hlab
                    X (typ_mu A) Hwf) as Hres;
      assert (Heenv : erase_env X (typ_mu A)
                        (X ~ bind_sub typ_top ++ nil) = nil);
      [ change (erase_env X (typ_mu A) ((X, bind_sub typ_top) :: nil) = nil);
        rewrite erase_env_cons_eq with (Y := X) (b := bind_sub typ_top)
          (E := nil) by reflexivity;
        reflexivity
      | rewrite Heenv in Hres;
        unfold open_tt in Hres;
        rewrite (@erase_open X (typ_mu A) 0
                   (typ_label X (open_tt_rec 0 X A0)) A0
                   (wf_lc_tt Hwf)) in Hres;
        rewrite erase_label_eq in Hres;
        rewrite (@erase_id X (typ_mu A) A0 HXfv HXfl) in Hres;
        unfold open_tt in *;
        exact Hres ]
  end.
Qed.

