import sys
from search import *
from functools import lru_cache

# extended generator with labels and records
@lru_cache(None)
def gen(n):
    if n<1: return frozenset()
    if n==1:
        return frozenset({('top',),('nat',),('bvar',0),('bvar',1),('rcd_nil',)})
    res=set()
    # arrow/all
    for a in range(1,n):
        b=n-1-a
        if b<1: continue
        for x in gen(a):
            for y in gen(b):
                res.add(('arrow',x,y)); res.add(('all',x,y))
    # mu, label
    for x in gen(n-1):
        res.add(('mu',x)); res.add(('label','l',x))
    # rcd_cons: 1 + a + b = n
    for a in range(1,n):
        b=n-1-a
        if b<1: continue
        for x in gen(a):
            for y in gen(b):
                if rt_type(y):
                    res.add(('rcd_cons','i',x,y))
    return frozenset(res)

def types_upto(N):
    s=set()
    for n in range(1,N+1): s|=set(gen(n))
    return [T for T in s if not collect(T,set())]

if __name__=='__main__':
    N=int(sys.argv[1])
    ts=types_upto(N)
    ts=[T for T in ts if tsize(T)<=N and wf((),('mu',T))]
    print('num',len(ts))
    import time
    t0=time.time();cands=0;hp=0
    for i,A in enumerate(ts):
        for B in ts:
            if A==B: continue
            hd=None
            for d in range(1,9):
                hd=subderiv((),('mu',A),('mu',B),d,set())
                if hd: break
            if not hd: continue
            hp+=1
            td=None
            for d in range(1,14):
                td=subderiv((),opens(A,('mu',A)),opens(B,('mu',B)),d,set())
                if td: break
            if td is None:
                cands+=1; print('CAND',A,B)
        if time.time()-t0>480:
            print('timeout at',i); break
    print('hyp pairs',hp,'cands',cands,'time',time.time()-t0)

