    def gen(s):
        if s<=0: return set()
        out={TOP,NAT}
        for v in vars: out.add(var(v))
        for a in range(1,s):
            b=s-1-a
            for x in bysize.get(a,set()):
                for y in bysize.get(b,set()):
                    out.add(arr(x,y))
                    out.add(lab('l',arr(x,y)))? 
        return out
    # simpler recursive depth-based generation, dedup
    seen=set()
    def rec(d, allow):
        if d<=0: return
        cand=[TOP,NAT]+[var(v) for v in vars]
        for t in cand: yield t
        if d>=1:
            for a in rec(d-1,allow):
                yield lab('l',a)
        if d>=2:
            for a in rec(d-1,allow):
                for b in rec(d-1,allow):
                    yield arr(a,b)
            # mu over x: body may use x
            for b in rec(d-1,allow+['x']):
                yield mu('x',b)
