import sys
sys.setrecursionlimit(100000)

# type encodings
# ('top',), ('nat',), ('bvar',k), ('fvar',name), ('arrow',a,b),
# ('all',s,t), ('mu',a), ('label',name,a)

def atoms(T, s):
    if T[0]=='fvar': s.add(T[1])
    elif T[0]=='label': s.add(T[1]); atoms(T[2],s)
    elif T[0] in ('arrow',): atoms(T[1],s); atoms(T[2],s)
    elif T[0]=='all': atoms(T[1],s); atoms(T[2],s)
    elif T[0]=='mu': atoms(T[1],s)
    return s

def collect(T,s):
    if T[0]=='fvar': s.add(T[1])
    elif T[0]=='label': s.add(T[1]); collect(T[2],s)
    elif T[0]=='arrow' or T[0]=='all': collect(T[1],s); collect(T[2],s)
    elif T[0]=='mu': collect(T[1],s)
    return s

# open_rec k U T, matching open_tt_rec (U assumed closed w.r.t bvars)
def orec(k,U,T):
    c=T[0]
    if c in ('top','nat'): return T
    if c=='bvar': return U if T[1]==k else T
    if c=='fvar': return T
    if c=='arrow': return ('arrow',orec(k,U,T[1]),orec(k,U,T[2]))
    if c=='all': return ('all',orec(k,U,T[1]),orec(k+1,U,T[2]))
    if c=='mu': return ('mu',orec(k+1,U,T[1]))
    if c=='label': return ('label',T[1],orec(k,U,T[2]))
    if c=='rcd_nil': return T
    if c=='rcd_cons': return ('rcd_cons',T[1],orec(k,U,T[2]),orec(k,U,T[3]))
    raise Exception(T)

def flat(T):
    # canonical rename of binder-local? we use distinct fresh atom names globally, so tuple equality ok
    return T

fresh_counter=[0]
def fresh(avoid):
    while True:
        fresh_counter[0]+=1
        n='a%d'%fresh_counter[0]
        if n not in avoid: return n

def all_atoms(*ts):
    s=set()
    for t in ts: collect(t,s)
    return s

def dom(env): return set(x for x,b in env)

def wf_env(env):
    if not env: return True
    (Y,b),E = env[0],env[1:]
    if not wf_env(E): return False
    if Y in dom(E): return False
    if b[0]=='sub':
        return wf(E,b[1])
    else:
        return wf(E,b[1])

def rt_type(T): return T[0] in ('rcd_nil','rcd_cons')

def collectLabel(T):
    if T[0]=='rcd_cons': return {T[1]} | collectLabel(T[3])
    return set()

def wf(env,T):
    c=T[0]
    if c in ('top','nat','rcd_nil'): return True
    if c=='bvar': return False
    if c=='fvar':
        return any(Y==T[1] and b[0]=='sub' for Y,b in env)
    if c=='arrow': return wf(env,T[1]) and wf(env,T[2])
    if c=='all':
        if not wf(env,T[1]): return False
        av=all_atoms(T)|dom(env)

        av=all_atoms(T)|dom(env)
        Y=fresh(av)
        return wf(((Y,('sub',T[1])),)+tuple(env), orec(0,('fvar',Y),T[2]))
    if c=='mu':
        av=all_atoms(T)|dom(env)
        Y=fresh(av)
        e2=((Y,('sub',('top',))),)+tuple(env)
        if not wf(e2, orec(0,('fvar',Y),T[1])): return False
        body=orec(0,('label',Y,orec(0,('fvar',Y),T[1])),T[1])
        return wf(e2, body)
    if c=='label': return wf(env,T[2])
    if c=='rcd_cons':
        return wf(env,T[2]) and wf(env,T[3]) and rt_type(T[3]) and (T[1] not in collectLabel(T[3]))
    raise Exception(T)

def binds(env,Y):
    for Z,b in env:
        if Z==Y: return b
    return None

# search sub derivations with a bounded depth. memo of failures per depth.
def subderiv(env,C,D,depth,stack):
    if depth<=0: return None
    key=(env,flat(C),flat(D))
    if key in stack: return None
    nstack=stack|{key}
    # sa_nat
    if C[0]=='nat' and D[0]=='nat' and wf_env(env):
        return ('nat',)
    # sa_fvar
    if C[0]=='fvar' and D[0]=='fvar' and C[1]==D[1] and wf_env(env) and wf(env,C):
        return ('fvar',C[1])
    # sa_top
    if D[0]=='top' and wf_env(env) and wf(env,C):
        return ('top',C)
    # sa_trans_tvar
    if C[0]=='fvar':
        b=binds(env,C[1])
        if b and b[0]=='sub':
            U=b[1]
            r=subderiv(env,U,D,depth-1,nstack)
            if r: return ('trans',C[1],U,r)
    # sa_arrow
    if C[0]=='arrow' and D[0]=='arrow':
        r1=subderiv(env,D[1],C[1],depth-1,nstack)
        r2=subderiv(env,C[2],D[2],depth-1,nstack) if r1 else None
        if r1 and r2: return ('arrow',r1,r2)
    # sa_all
    if C[0]=='all' and D[0]=='all':
        r1=subderiv(env,C[1],D[1],depth-1,nstack)
        r2=subderiv(env,D[1],C[1],depth-1,nstack) if r1 else None
        if r1 and r2:
            av=all_atoms(C,D)|dom(env)
            Y=fresh(av)
            r3=subderiv(((Y,('sub',D[1])),)+tuple(env), orec(0,('fvar',Y),C[2]), orec(0,('fvar',Y),D[2]),depth-1,nstack)
            if r3: return ('all',r1,r2,r3)
    # sa_label
    if C[0]=='label' and D[0]=='label' and C[1]==D[1]:
        r=subderiv(env,C[2],D[2],depth-1,nstack)
        if r: return ('label',r)
    # sa_rcd
    if C[0] in ('rcd_nil','rcd_cons') and D[0] in ('rcd_nil','rcd_cons'):
        if rt_type(C) and rt_type(D) and collectLabel(D) <= collectLabel(C) and wf_env(env) and wf(env,C) and wf(env,D):
            # field-wise: for each label in D, lookup both and sub
            def tl(i,T):
                if T[0]=='rcd_cons':
                    return T[2] if T[1]==i else tl(i,T[3])
                return None
            ok=True; subs=[]
            for i in sorted(collectLabel(D)):
                t1=tl(i,C); t2=tl(i,D)
                if t1 is None: ok=False; break
                r=subderiv(env,t1,t2,depth-1,nstack)
                if not r: ok=False; break
                subs.append(r)
            if ok: return ('rcd',subs)
    # sa_rec
    if C[0]=='mu' and D[0]=='mu':
