    tag=T[0]
    if tag=='nat' or tag=='top': return T
    if tag=='bvar': return arg if T[1]==k else T
    if tag=='fvar': return T
    if tag=='arrow': return arr(open_tt(T[1],arg,k), open_tt(T[2],arg,k))
    if tag=='label': return lab(T[1], open_tt(T[2],arg,k))
    if tag=='mu': return mu(open_tt(T[1],arg,k+1))
    raise Exception(T)

